import{a2 as t,P as e,Q as d,_ as r}from"./framework-04579a5f.js";const a={},s=r('<h2 id="what-each-state-means" tabindex="-1"><a class="header-anchor" href="#what-each-state-means" aria-hidden="true">#</a> What each state means</h2><table><thead><tr><th>State</th><th>Player behavior</th></tr></thead><tbody><tr><td>idle</td><td>Idle. A freshly constructed <code>FPlayer</code> sits here. <br> It holds a little memory and starts no extra threads. <br> From idle, only <code>setDataSource</code> can move it to <code>initialized</code>.</td></tr><tr><td>initialized</td><td>Initialized. Compared with idle, the player now knows the input media source. Still no extra threads.</td></tr><tr><td>asyncPreparing</td><td>Asynchronously preparing. You get here by calling <code>prepareAsync</code> from <code>initialized</code>. <br> This isn&#39;t a stable state: it waits for specific work to finish, then flips to <code>prepared</code> on its own. <br> That work covers probing the media type, opening the file, opening decoders and starting decode threads, starting a read thread, opening the audio output device, and starting video output threads.</td></tr><tr><td>prepared</td><td><code>asyncPreparing</code> lands here once its work is done. <br> Some audio and video has already been buffered and decoded, so playback can begin at any moment.</td></tr><tr><td>started</td><td>Media (video or audio) is playing.</td></tr><tr><td>paused</td><td>Playback of media (video or audio) is paused.</td></tr><tr><td>completed</td><td>Playback of media (video or audio) finished. You can play it again from the start.</td></tr><tr><td>stopped</td><td>Every thread has released its resources. The audio device is closed.</td></tr><tr><td>end</td><td>Every buffer that needed manual release has been freed. <br> A player in this state just waits for garbage collection to reclaim the rest.</td></tr><tr><td>error</td><td>The player hit an error.</td></tr></tbody></table><h3 id="playable-states" tabindex="-1"><a class="header-anchor" href="#playable-states" aria-hidden="true">#</a> Playable states</h3><p><code>prepared</code>, <code>started</code>, <code>paused</code>, <code>completed</code>.<br> From any playable state, <code>start</code> moves the player to <strong>started</strong> and playback runs.</p><h3 id="stable-states" tabindex="-1"><a class="header-anchor" href="#stable-states" aria-hidden="true">#</a> Stable states</h3><p><code>idle</code>, <code>initialized</code>, <code>prepared</code>, <code>paused</code>, <code>completed</code>, <code>stopped</code>, <code>end</code>, <code>error</code>.<br> A stable state only changes when an API call moves it. It never shifts on its own.</p><h3 id="unstable-states" tabindex="-1"><a class="header-anchor" href="#unstable-states" aria-hidden="true">#</a> Unstable states</h3><p><code>asyncPreparing</code>, <code>started</code>.<br> An unstable state changes on its own once conditions are met, and API calls can also push it to another state.</p><h2 id="every-transition" tabindex="-1"><a class="header-anchor" href="#every-transition" aria-hidden="true">#</a> Every transition</h2><h3 id="idle" tabindex="-1"><a class="header-anchor" href="#idle" aria-hidden="true">#</a> <strong>idle</strong></h3><table><thead><tr><th>API call</th><th>Target state</th></tr></thead><tbody><tr><td>setDataSource()</td><td>initialized</td></tr><tr><td>reset()</td><td>idle</td></tr><tr><td>release()</td><td>end</td></tr></tbody></table><h3 id="initialized" tabindex="-1"><a class="header-anchor" href="#initialized" aria-hidden="true">#</a> <strong>initialized</strong></h3><table><thead><tr><th>API call</th><th>Target state</th></tr></thead><tbody><tr><td>prepareAsync()</td><td>asyncPreparing</td></tr><tr><td>reset()</td><td>idle</td></tr><tr><td>release()</td><td>end</td></tr></tbody></table><h3 id="asyncpreparing" tabindex="-1"><a class="header-anchor" href="#asyncpreparing" aria-hidden="true">#</a> <strong>asyncPreparing</strong></h3><table><thead><tr><th>API call</th><th>Target state</th></tr></thead><tbody><tr><td>Preparation completes</td><td>prepared</td></tr><tr><td>An error occurs</td><td>error</td></tr><tr><td>reset()</td><td>idle</td></tr><tr><td>release()</td><td>end</td></tr></tbody></table><h3 id="prepared" tabindex="-1"><a class="header-anchor" href="#prepared" aria-hidden="true">#</a> <strong>prepared</strong></h3><table><thead><tr><th>API call</th><th>Target state</th></tr></thead><tbody><tr><td>seekTo()</td><td>prepared</td></tr><tr><td>start()</td><td>started</td></tr><tr><td>reset()</td><td>idle</td></tr><tr><td>release()</td><td>end</td></tr></tbody></table><h3 id="started" tabindex="-1"><a class="header-anchor" href="#started" aria-hidden="true">#</a> <strong>started</strong></h3><table><thead><tr><th>API call</th><th>Target state</th></tr></thead><tbody><tr><td>seekTo()</td><td>started</td></tr><tr><td>start()</td><td>started</td></tr><tr><td>pause()</td><td>paused</td></tr><tr><td>stop()</td><td>stopped</td></tr><tr><td>Playback completes</td><td>completed</td></tr><tr><td>An error occurs</td><td>error</td></tr><tr><td>reset()</td><td>idle</td></tr><tr><td>release()</td><td>end</td></tr></tbody></table><h3 id="paused" tabindex="-1"><a class="header-anchor" href="#paused" aria-hidden="true">#</a> <strong>paused</strong></h3><table><thead><tr><th>API call</th><th>Target state</th></tr></thead><tbody><tr><td>seekTo()</td><td>paused</td></tr><tr><td>start()</td><td>started</td></tr><tr><td>pause()</td><td>paused</td></tr><tr><td>stop()</td><td>stopped</td></tr><tr><td>reset()</td><td>idle</td></tr><tr><td>release()</td><td>end</td></tr></tbody></table><h3 id="completed" tabindex="-1"><a class="header-anchor" href="#completed" aria-hidden="true">#</a> <strong>completed</strong></h3><table><thead><tr><th>API call</th><th>Target state</th></tr></thead><tbody><tr><td>seekTo()</td><td>paused</td></tr><tr><td>start()</td><td>started (from the beginning)</td></tr><tr><td>pause()</td><td>paused</td></tr><tr><td>stop()</td><td>stopped</td></tr><tr><td>reset()</td><td>idle</td></tr><tr><td>release()</td><td>end</td></tr></tbody></table><h3 id="stopped" tabindex="-1"><a class="header-anchor" href="#stopped" aria-hidden="true">#</a> <strong>stopped</strong></h3><table><thead><tr><th>API call</th><th>Target state</th></tr></thead><tbody><tr><td>stop()</td><td>stopped</td></tr><tr><td>prepareAsync()</td><td>asyncPreparing</td></tr><tr><td>reset()</td><td>idle</td></tr><tr><td>release()</td><td>end</td></tr></tbody></table><h3 id="error" tabindex="-1"><a class="header-anchor" href="#error" aria-hidden="true">#</a> <strong>error</strong></h3><table><thead><tr><th>API call</th><th>Target state</th></tr></thead><tbody><tr><td>reset()</td><td>idle</td></tr><tr><td>release()</td><td>end</td></tr></tbody></table><h3 id="end" tabindex="-1"><a class="header-anchor" href="#end" aria-hidden="true">#</a> <strong>end</strong></h3><table><thead><tr><th>API call</th><th>Target state</th></tr></thead><tbody><tr><td>release()</td><td>end</td></tr></tbody></table>',29),o=[s];function n(h,i){return e(),d("div",null,o)}const c=t(a,[["render",n],["__file","status.html.vue"]]);export{c as default};
